-- The ISO add-on's tables, part 2 (docs/iso/model.md §1, §3.5-3.13, §6; ISO-2e): risk items and controls, objectives
-- and readings, audit programmes, internal audits and their checklists, findings, nonconformities with their incident
-- fields, actions, management reviews with their inputs and outputs, and the remaining iso_file subject columns.
-- Generated by drizzle-kit, then the custom part at the end (forced RLS, grants, triggers, the purge list).

-- A list of enum values holds no value twice (standard codes, life-cycle stages, exposed groups). The checks call it.
CREATE FUNCTION canopy_values_distinct(vals anyarray) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog
AS $$
  SELECT count(DISTINCT x) = count(*) FROM unnest(vals) AS x
$$;
--> statement-breakpoint
