CREATE TABLE "nonconformity" (
	"id" uuid PRIMARY KEY DEFAULT canopy_uuid_v7() NOT NULL,
	"firm_id" uuid DEFAULT app_firm_id() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"archived_at" timestamp with time zone,
	"version" integer DEFAULT 1 NOT NULL,
	"client_id" uuid NOT NULL,
	"management_system_id" uuid NOT NULL,
	"number" integer NOT NULL,
	"source" "nc_source" NOT NULL,
	"source_instance_id" uuid,
	"raised_from_risk_item_id" uuid,
	"severity" "nc_severity" NOT NULL,
	"standards" "iso_standard_code"[] NOT NULL,
	"clause_ids" uuid[] DEFAULT '{}'::uuid[] NOT NULL,
	"unit_id" uuid,
	"description" text NOT NULL,
	"reported_by_id" uuid NOT NULL,
	"reported_on" date NOT NULL,
	"containment" text,
	"correction" text,
	"disposition" "nc_disposition",
	"disposition_authorised_by_id" uuid,
	"root_cause_method" "root_cause_method",
	"root_cause" text,
	"similar_occurrences" text,
	"risk_review" text,
	"system_change" text,
	"no_action_reason" text,
	"owner_id" uuid NOT NULL,
	"approver_id" uuid NOT NULL,
	"due_on" date NOT NULL,
	"effectiveness_due_on" date,
	"effectiveness_note" text,
	"effective" boolean,
	"closed_on" date,
	"cancel_reason" text,
	"state" "nc_state" DEFAULT 'OPEN' NOT NULL,
	"incident_occurred_at" timestamp with time zone,
	"incident_location" text,
	"incident_type" "incident_type",
	"incident_outcome" "incident_outcome",
	"incident_person_category" "incident_person_category",
	"incident_lost_days" integer,
	"incident_reportable" boolean,
	"statutory_instance_id" uuid,
	"incident_worker_participation" boolean,
	CONSTRAINT "nonconformity_scope_key" UNIQUE("firm_id","client_id","id"),
	CONSTRAINT "nonconformity_number_key" UNIQUE("firm_id","client_id","number"),
	CONSTRAINT "nonconformity_number_check" CHECK (number >= 1),
	CONSTRAINT "nonconformity_standards_check" CHECK (cardinality(standards) between 1 and 3 and canopy_values_distinct(standards)),
	CONSTRAINT "nonconformity_clauses_check" CHECK (cardinality(clause_ids) <= 20 and canopy_ids_distinct(clause_ids)),
	CONSTRAINT "nonconformity_maker_checker_check" CHECK (owner_id <> approver_id),
	CONSTRAINT "nonconformity_due_check" CHECK (due_on >= reported_on),
	CONSTRAINT "nonconformity_disposition_check" CHECK ((disposition is null) = (disposition_authorised_by_id is null)),
	CONSTRAINT "nonconformity_root_cause_check" CHECK (state not in ('ROOT_CAUSE_FOUND', 'ACTIONS_PLANNED', 'AWAITING_VERIFICATION', 'CLOSED') or num_nonnulls(containment, correction, root_cause_method, root_cause, similar_occurrences) = 5),
	CONSTRAINT "nonconformity_submitted_check" CHECK (state not in ('AWAITING_VERIFICATION', 'CLOSED') or (risk_review is not null and system_change is not null)),
	CONSTRAINT "nonconformity_closed_check" CHECK ((state = 'CLOSED') = (closed_on is not null) and (state <> 'CLOSED' or (effective and effectiveness_note is not null)) and (closed_on is null or closed_on >= reported_on)),
	CONSTRAINT "nonconformity_cancel_check" CHECK ((state = 'CANCELLED') = (cancel_reason is not null)),
	CONSTRAINT "nonconformity_incident_check" CHECK (num_nonnulls(incident_occurred_at, incident_location, incident_type, incident_outcome, incident_reportable, incident_worker_participation) = case when source in ('INCIDENT', 'NEAR_MISS') then 6 else 0 end and (incident_type is not null or num_nonnulls(incident_person_category, incident_lost_days, statutory_instance_id) = 0)),
	CONSTRAINT "nonconformity_incident_unit_check" CHECK (source not in ('INCIDENT', 'NEAR_MISS') or unit_id is not null),
	CONSTRAINT "nonconformity_near_miss_check" CHECK (incident_type is null or ((incident_type = 'NEAR_MISS') = (source = 'NEAR_MISS') and (incident_type <> 'NEAR_MISS' or incident_outcome = 'NONE'))),
	CONSTRAINT "nonconformity_lost_days_check" CHECK ((incident_lost_days is not null) = (incident_outcome is not distinct from 'LOST_TIME') and (incident_lost_days is null or incident_lost_days between 1 and 10000)),
	CONSTRAINT "nonconformity_version_check" CHECK (version >= 1)
);
--> statement-breakpoint
