CREATE TABLE "risk_item" (
	"id" uuid PRIMARY KEY DEFAULT canopy_uuid_v7() NOT NULL,
	"firm_id" uuid DEFAULT app_firm_id() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"archived_at" timestamp with time zone,
	"version" integer DEFAULT 1 NOT NULL,
	"client_id" uuid NOT NULL,
	"management_system_id" uuid NOT NULL,
	"kind" "risk_kind" NOT NULL,
	"unit_id" uuid,
	"activity" text NOT NULL,
	"description" text NOT NULL,
	"impact" text,
	"life_cycle_stages" "life_cycle_stage"[] DEFAULT '{}' NOT NULL,
	"control_type" "aspect_control_type",
	"routine" boolean,
	"persons_exposed" "persons_exposed"[] DEFAULT '{}' NOT NULL,
	"condition" "operating_condition",
	"assessed_with" text,
	"likelihood" integer NOT NULL,
	"severity" integer NOT NULL,
	"residual_likelihood" integer,
	"residual_severity" integer,
	"rating" integer NOT NULL,
	"residual_rating" integer,
	"significant" boolean NOT NULL,
	"significant_override" boolean,
	"significance_reason" text,
	"obligation_ids" uuid[] DEFAULT '{}'::uuid[] NOT NULL,
	"climate_related" boolean DEFAULT false NOT NULL,
	"owner_id" uuid NOT NULL,
	"review_due_on" date,
	"last_reviewed_on" date,
	CONSTRAINT "risk_item_scope_key" UNIQUE("firm_id","client_id","id"),
	CONSTRAINT "risk_item_scales_check" CHECK (likelihood between 1 and 5 and severity between 1 and 5 and rating between 1 and 25),
	CONSTRAINT "risk_item_residual_check" CHECK ((residual_likelihood is null) = (residual_severity is null) and (residual_likelihood is null) = (residual_rating is null) and (residual_likelihood is null or (residual_likelihood between 1 and 5 and residual_severity between 1 and 5 and residual_rating between 1 and 25))),
	CONSTRAINT "risk_item_impact_check" CHECK (kind not in ('ASPECT', 'HAZARD') or impact is not null),
	CONSTRAINT "risk_item_aspect_check" CHECK ((kind = 'ASPECT') = (cardinality(life_cycle_stages) > 0) and (kind = 'ASPECT') = (control_type is not null) and canopy_values_distinct(life_cycle_stages)),
	CONSTRAINT "risk_item_hazard_check" CHECK ((kind = 'HAZARD') = (cardinality(persons_exposed) > 0) and (kind = 'HAZARD') = (routine is not null) and canopy_values_distinct(persons_exposed)),
	CONSTRAINT "risk_item_condition_check" CHECK ((kind in ('ASPECT', 'HAZARD')) = (condition is not null)),
	CONSTRAINT "risk_item_override_check" CHECK ((significant_override is null) = (significance_reason is null)),
	CONSTRAINT "risk_item_obligations_check" CHECK (cardinality(obligation_ids) <= 50 and canopy_ids_distinct(obligation_ids)),
	CONSTRAINT "risk_item_version_check" CHECK (version >= 1)
);
--> statement-breakpoint
