-- An NC's number counts per client from 1 (model §3.10). The trigger sets it on insert, whatever the writer passed,
-- under a transaction lock on the client so two raises never take the same number; the unique key backs it. Rows are
-- never deleted, so a number is never reused. On update the number stays.
CREATE FUNCTION canopy_nonconformity_number() RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.number := OLD.number;
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('nonconformity_number:' || NEW.client_id::text, 0));
  SELECT coalesce(max(n.number), 0) + 1 INTO NEW.number
    FROM nonconformity n WHERE n.firm_id = NEW.firm_id AND n.client_id = NEW.client_id;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER "nonconformity_number" BEFORE INSERT OR UPDATE OF "number" ON "nonconformity"
  FOR EACH ROW EXECUTE FUNCTION canopy_nonconformity_number();--> statement-breakpoint

-- The account purge (ADR M15-0002, migration 0035) covers the new tables: listed children first, each with the
-- purge role's grants and policies.
CREATE OR REPLACE FUNCTION canopy_purge_tables() RETURNS text[]
LANGUAGE sql IMMUTABLE
SET search_path = public, pg_temp
AS $$
  SELECT ARRAY[
    'iso_file', 'review_output', 'review_input', 'management_review_person', 'risk_control', 'iso_action',
    'management_review', 'audit_checklist_item', 'audit_finding', 'nonconformity_document', 'nonconformity_risk_item',
    'nonconformity_person', 'nonconformity', 'internal_audit_person', 'internal_audit_unit', 'internal_audit',
    'audit_programme', 'objective_reading', 'objective_risk_item', 'objective', 'risk_item',
    'certification_unit', 'certification', 'external_audit', 'document_revision', 'controlled_document',
    'clause_assessment', 'context_item', 'management_system_unit', 'management_system',
    'iso_review_output_def', 'iso_review_input_def', 'iso_clause', 'iso_standard',
    'auth_token', 'auth_session', 'auth_credential', 'idempotency_key', 'notification_send',
    'import_issue', 'import_row', 'import_batch', 'mapping_template', 'export_job',
    'evidence', 'comment', 'compliance_instance', 'assignment', 'obligation', 'act', 'category',
    'unit', 'company', 'location', 'department', 'auth_invite', 'support_grant', 'membership',
    'audit_event', 'domain_event', 'person', 'client'
  ]::text[]
$$;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['review_output', 'review_input', 'management_review_person', 'risk_control', 'iso_action',
    'management_review', 'audit_checklist_item', 'audit_finding', 'nonconformity_document', 'nonconformity_risk_item',
    'nonconformity_person', 'nonconformity', 'internal_audit_person', 'internal_audit_unit', 'internal_audit',
    'audit_programme', 'objective_reading', 'objective_risk_item', 'objective', 'risk_item'] LOOP
    EXECUTE format('GRANT SELECT ("firm_id"), DELETE ON %I TO canopy_purge', t);
    EXECUTE format('CREATE POLICY purge_read ON %I FOR SELECT TO canopy_purge USING (firm_id = app_firm_id())', t);
    EXECUTE format('CREATE POLICY purge_delete ON %I FOR DELETE TO canopy_purge USING (firm_id = app_firm_id())', t);
  END LOOP;
END
$$;
